19: const EM_DASH = String.fromCharCode(0x2014)
20: const EN_DASH = String.fromCharCode(0x2013)
21: const MINUS_SIGN = String.fromCharCode(0x2212)
22: const DOUBLE_HYPHEN = '-'.repeat(2)
23: const SPACED_HYPHEN = [' ', '-', ' '].join('')
24: 
25: /** Prose characters a JSX text node may hold before we read it as copy. */
26: const PROSE = /^[\p{L}\p{N} .,:()'"/!?&+%-]+$/u
27: 
28: /** E2 and E3 files that do not live in an auto scanned directory. */
29: const EXPLICIT_FILES: readonly string[] = [
30:   'src/App.tsx',
31:   'src/app.smoke.test.ts',
32:   'src/dashScan.test.ts',
33:   'src/data/profiles.ts',
34:   'src/data/profiles.test.ts',
35:   'src/lib/forecast.test.ts',
36:   'src/lib/forecast.ts',
37:   'src/lib/format.ts',
38:   'src/lib/metrics.ts',
39:   'src/lib/planText.ts',
40:   'src/lib/planText.test.ts',
41:   'src/lib/shockPresets.ts',
42:   'src/lib/shocks.golden.test.ts',
43:   'src/lib/shocks.test.ts',
44:   'src/lib/shocks.ts',
45:   'src/lib/verdict.ts',
46:   'src/lib/verdict.test.ts',
47: ]
48: 
49: /** Directories whose every source file is part of these phases. */
50: const AUTO_DIRS: readonly string[] = [
51:   'src/state',
52:   'src/components/console',
53:   'src/components/weather',
54: ]
55: 
56: /** Stylesheets written this phase, scanned without the double hyphen rule. */
57: const CSS_FILES: readonly string[] = ['src/index.css']
58: 
59: function listDir(directory: string): string[] {
60:   const out: string[] = []
61:   for (const name of readdirSync(directory)) {
62:     const path = join(directory, name)
63:     if (statSync(path).isDirectory()) {
64:       out.push(...listDir(path))
65:     } else if (/\.(ts|tsx)$/.test(name)) {
66:       out.push(path)
67:     }
68:   }
69:   return out
70: }
71: 
72: function targetFiles(): string[] {
73:   const paths = [...EXPLICIT_FILES]
74:   for (const directory of AUTO_DIRS) {
75:     paths.push(...listDir(directory))
76:   }
77:   return [...new Set(paths)].sort()
78: }
79: 
80: interface Prose {
81:   file: string
82:   line: number
83:   chunk: string
84:   where: string
85: }
86: 
87: function lineOf(text: string, index: number): number {
88:   return text.slice(0, index).split('\n').length
89: }
90: 
91: /** Pull every piece of prose out of one source file. */
92: function proseOf(file: string, text: string): Prose[] {
93:   const prose: Prose[] = []
94:   let rest = text
95: 
96:   const push = (chunk: string, index: number, where: string): void => {
97:     prose.push({ file, line: lineOf(text, index), chunk, where })
98:   }
99: 
100:   // Block comments first, then line comments, so an apostrophe inside a
101:   // comment can never open a string that swallows real code.
102:   rest = rest.replace(/\/\*[\s\S]*?\*\//g, (chunk, index: number) => {
103:     push(chunk, index, 'block comment')
104:     return ' '
105:   })
106:   rest = rest.replace(/\/\/[^\n]*/g, (chunk, index: number) => {
107:     push(chunk, index, 'line comment')
108:     return ' '
109:   })
110: 
111:   const stringPattern = /'(?:[^'\\\n]|\\.)*'|"(?:[^"\\\n]|\\.)*"|`(?:[^`\\]|\\.)*`/g
112:   let match: RegExpExecArray | null
113:   while ((match = stringPattern.exec(rest)) !== null) {
114:     // Template expressions are code, not copy.
115:     const chunk = match[0].replace(/\$\{[^}]*\}/g, '')
116:     push(chunk, match.index, 'string literal')
117:   }
118:   rest = rest.replace(stringPattern, ' ')
119: 
120:   // JSX text nodes: prose between a tag close and the next tag open.
121:   const jsxPattern = />([^<>{}]+)</g
122:   while ((match = jsxPattern.exec(rest)) !== null) {
123:     const chunk = match[1] ?? ''
124:     if (PROSE.test(chunk) && /[A-Za-z]/.test(chunk)) {
125:       push(chunk, match.index, 'jsx text')
126:     }
127:   }
128: 
129:   return prose
130: }
131: 
132: function violationsIn(chunk: string): string[] {
133:   const problems: string[] = []
134:   if (chunk.includes(EM_DASH)) {
135:     problems.push('em dash')
136:   }
137:   if (chunk.includes(EN_DASH)) {
138:     problems.push('en dash')
139:   }
140:   if (chunk.includes(MINUS_SIGN)) {
141:     problems.push('minus sign')
142:   }
143:   if (chunk.includes(DOUBLE_HYPHEN)) {
144:     problems.push('double hyphen')
145:   }
146:   if (chunk.includes(SPACED_HYPHEN)) {
147:     problems.push('spaced hyphen')
148:   }
149:   return problems
150: }
151: 
152: describe('content rule: dash scan over the Phase E2 and E3 sources', () => {
153:   const files = targetFiles()
154: 
155:   it('covers every file these phases wrote', () => {
156:     expect(files).toContain('src/components/console/ConsoleView.tsx')
157:     expect(files).toContain('src/state/consoleStore.ts')
158:     expect(files).toContain('src/lib/forecast.ts')
159:     expect(files).toContain('src/lib/forecast.test.ts')
160:     expect(files).toContain('src/components/weather/WeatherPanel.tsx')
161:     expect(files).toContain('src/components/weather/ForecastStrip.test.ts')
162:     expect(files.length).toBeGreaterThanOrEqual(20)
163:   })
164: 
165:   it('keeps dash code points and dash copy out of every file', () => {
166:     const found: string[] = []
167:     for (const file of files) {
168:       const text = readFileSync(file, 'utf8')
169:       const lines = text.split('\n')
170:       lines.forEach((line, index) => {
171:         for (const character of [EM_DASH, EN_DASH, MINUS_SIGN]) {
172:           if (line.includes(character)) {
173:             found.push(`${file}:${index + 1}: dash code point in source`)
174:           }
175:         }
176:       })
177:       for (const entry of proseOf(file, text)) {
178:         for (const problem of violationsIn(entry.chunk)) {
179:           const excerpt = entry.chunk.trim().slice(0, 120)
180:           found.push(`${file}:${entry.line}: ${problem} in ${entry.where}: ${excerpt}`)
181:         }
182:       }
183:     }
184:     expect(found).toEqual([])
185:   })
186: 
187:   it('keeps the console stylesheet free of dash copy', () => {
188:     // CSS is scanned too, with one exception: a custom property name
189:     // begins with two hyphens, which is syntax rather than copy, and CSS
190:     // holds no user facing copy beyond the comments checked here.
191:     const found: string[] = []
192:     for (const file of CSS_FILES) {
193:       const text = readFileSync(file, 'utf8')
194:       const lines = text.split('\n')
195:       lines.forEach((line, index) => {
196:         for (const character of [EM_DASH, EN_DASH, MINUS_SIGN]) {
197:           if (line.includes(character)) {
