import { readFileSync } from 'node:fs'
const EM = String.fromCharCode(0x2014)
const EN = String.fromCharCode(0x2013)
const MINUS = String.fromCharCode(0x2212)
const DOUBLE = '-'.repeat(2)
const SPACED = [' ', '-', ' '].join('')
const PROSE = /^[\p{L}\p{N} .,:()'\"/?&!+%-]+\$/u
function lineOf(text, index) { return text.slice(0, index).split('\n').length }
function proseOf(file, text) {
  const prose = []
  let rest = text
  const push = (chunk, index, where) => prose.push({ file, line: lineOf(text, index), chunk, where })
  rest = rest.replace(/\/\*[\s\S]*?\*\//g, (chunk, index) => { push(chunk, index, 'block comment'); return ' ' })
  rest = rest.replace(/\/\/[^\n]*/g, (chunk, index) => { push(chunk, index, 'line comment'); return ' ' })
  const stringPattern = /'(?:[^'\\\\\n]|\\\\.)*'|\"(?:[^\"\\\\\n]|\\\\.)*\"|\`(?:[^\`\\\\]|\\\\.)*\`/g
  let match
  while ((match = stringPattern.exec(rest)) !== null) {
    const chunk = match[0].replace(/\\\$\{[^}]*\}/g, '')
    push(chunk, match.index, 'string literal')
  }
  rest = rest.replace(stringPattern, ' ')
  const jsxPattern = />([^<>{}]+)</g
  while ((match = jsxPattern.exec(rest)) !== null) {
    const chunk = match[1] ?? ''
    if (PROSE.test(chunk) && /[A-Za-z]/.test(chunk)) push(chunk, match.index, 'jsx text')
  }
  return prose
}
function violationsIn(chunk) {
  const p = []
  if (chunk.includes(EM)) p.push('em dash')
  if (chunk.includes(EN)) p.push('en dash')
  if (chunk.includes(MINUS)) p.push('minus sign')
  if (chunk.includes(DOUBLE)) p.push('double hyphen')
  if (chunk.includes(SPACED)) p.push('spaced hyphen')
  return p
}
const files = ['src/lib/planMath.ts', 'src/lib/planMath.test.ts', 'src/lib/planMath.golden.test.ts']
