      console.log(file + ':' + entry.line + ': ' + problem + ' in ' + entry.where + ': ' + entry.chunk.trim().slice(0, 110).replace(/\n/g, ' '))
      bad++
    }
  }
}
console.log(bad === 0 ? 'ALL CLEAN' : bad + ' violations')
